-- The turning catalog brands' code keys (Code keys -> Turning, Parting, Grooving,
-- Groove-Turn, Face Grooving, Profiling, Threading, Turning for Swiss-Type), from
-- the ISCAR turning catalog and e-catalog families; each kept if one exists.

INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.tl.quickturn', $ck${"title": "QUICK-TURN code key – turning tools and inserts", "subtitle": "QUICK-TURN tool and insert families from the ISCAR turning catalog", "example": "Q6-DMXNL 2525M-12-SL-JHP", "decoder": "tl-quickturn", "sections": [{"key": "t-family", "title": "Tool / insert family", "sample": "DMXNL", "rows": [{"code": "DMXNL", "meaning": "Safety Lock Tools with High Feed Negative Inserts for Roughing Applications"}, {"code": "DMXNR", "meaning": "Safety Lock Tools with High Feed Negative Inserts for Roughing Applications"}, {"code": "MNMG120608", "meaning": "High Feed Insert with Six Reinforced Cutting Edges and Negative Flank for Roughing Applications"}, {"code": "DMXNN", "meaning": "Safety Lock Tools with High Feed Negative Inserts for Roughing Applications"}]}, {"key": "t-adapt", "title": "Adaptation", "rows": [{"code": "C#", "meaning": "CAMFIX polygonal taper adaptation size"}, {"code": "HSK", "meaning": "HSK adaptation"}, {"code": "AVC", "meaning": "Anti-vibration (WHISPERLINE) bar"}, {"code": "VDI", "meaning": "VDI adaptation"}, {"code": "KIT", "meaning": "Kit"}]}, {"key": "t-size", "title": "Insert size", "rows": [{"code": "######", "meaning": "Insert size, thickness code and corner radius"}]}, {"key": "t-shank", "title": "Shank", "rows": [{"code": "####", "meaning": "Shank height × width in mm"}, {"code": "####X", "meaning": "Shank height × width, then the tool length letter (A = 32 … Y = 500 mm)"}]}, {"key": "t-dims", "title": "Dimensions", "rows": [{"code": "##", "meaning": "Insert size, width, depth, pitch or TPI (see the catalog)"}, {"code": "#.##", "meaning": "Width, corner radius, pitch or depth in mm (see the catalog)"}, {"code": "D##", "meaning": "Minimum bore or bar diameter in mm"}]}, {"key": "t-hand", "title": "Hand", "rows": [{"code": "R", "meaning": "Right-hand"}, {"code": "L", "meaning": "Left-hand"}, {"code": "N", "meaning": "Neutral"}]}, {"key": "t-option", "title": "Options", "rows": [{"code": "JHP", "meaning": "JETHP: high-pressure coolant through the tool"}, {"code": "MC", "meaning": "Multi-coolant connection"}, {"code": "SL", "meaning": "Safety-lock clamping"}, {"code": "Y", "meaning": "Y-axis tool"}, {"code": "IQ", "meaning": "IQ version"}]}, {"key": "t-grade", "title": "Grade", "rows": [{"code": "ICxxx", "meaning": "Carbide grade"}]}, {"key": "t-suffix", "title": "Version / chipformer", "rows": [{"code": "…", "meaning": "Version, chipformer or dimension code (see the catalog)"}]}]}$ck$)
